add(532,'الشيخ، فتأمّله.','это. Поразмысли над этим.',False,True)
add(532,'وقولهم: «فني من لم يكن، وبقي من لم يزل»، إن أرادوا به: فني في الوجود الخارجيّ، فهذا مكابرة. وإن أرادوا به أنّه فني في الشهود، فهذا نقص في الإيمان والتوحيد كما تقرّر. وإن أرادوا به أنّه فني في القصد والإرادة والمحبّة، فهذا هو الحقّ، وهو الفناء عن إرادة السوى وقصده ومحبّته.','Их слова: «Исчез тот, кого не было, и остался Тот, Кто был всегда». Если они подразумевают исчезновение во внешнем существовании, то это упрямое отрицание очевидного. Если подразумевают исчезновение из созерцания, то это недостаток веры и единобожия, как уже установлено. Если же подразумевают исчезновение из направленности стремления, воли и любви, то это истина: фана от желания иного, стремления к нему и любви к нему.')
add(532,'قوله: (هذا توحيد الخاصّة، الذي يصحّ بعلم الفناء، ويصفو في علم الجمع، ويجذب إلى توحيد أرباب الجمع)، يعني: توحيد المتوسّطين الذين ارتفعوا عن العامّة، ولم يصلوا إلى منزل خاصّة الخاصّة.','Его слова: «Это единобожие избранных, которое становится правильным благодаря знанию фана, очищается в знании собранности и влечёт к единобожию людей собранности». Он имеет в виду единобожие находящихся посередине: они поднялись над обычными людьми, но не достигли обители избранных из избранных.')
add(532,'قوله: (يصحّ بعلم الفناء)، ولم يقل: بحقيقة الفناء، لأنّ درجة العلم في هذا السلوك قبل درجة الحال والمعرفة، وصاحب هذه الدرجة متوسّط لم يبلغ الغاية، وحال الفناء لصاحب الدرجة الثالثة.','Его слова: «Становится правильным благодаря знанию фана». Он не сказал: действительностью фана, — потому что на этом пути ступень знания предшествует ступени состояния и познания. Обладатель этой ступени находится посередине, ещё не достиг предела, а состояние фана принадлежит обладателю третьей ступени.')
add(532,'وكذلك قوله: (ويصفو في علم الجمع)، فإنّ علم الجمع قبل حال الجمع، كما تقدّم في بابه.','Так же и слова: «Очищается в знании собранности». Ведь знание собранности предшествует состоянию собранности, как уже говорилось в соответствующей главе.')
add(532,'قوله: (ويجذب إلى توحيد أرباب الجمع)، يريد: أنّ هذا المقام يجذب أهله إلى توحيد الفريق الذين فوقهم، وهم أصحاب الجمع.','Его слова: «И влечёт к единобожию людей собранности». Он хочет сказать, что эта стоянка влечёт её обладателей к единобожию тех, кто выше них, — людей собранности.')
add(532,'وقد تقدّم ذكر الجمع، ولم يحصل به الشفاء. ونحن الآن ذاكرون حقيقته وأقسامه، والصحيح منه والمعلول. والله المستعان.','О собранности уже говорилось, но это не дало полного удовлетворения. Теперь мы изложим её сущность, разновидности, то, что в ней правильно и что имеет изъяны. К Аллаху обращаются за помощью.')
add(532,'الجمع في اللغة: الضمّ. والاجتماع: الانضمام. والتفريق: ضدّه. وأمّا في','В языке «джам» — собирание, соединение; «иджтима» — соединение вместе; различение — противоположность этому. А в',False)
add(533,'اصطلاح القوم: فهو شخوص البصيرة إلى من صدرت عنه المتفرّقات كلّها. وهو ثلاثة أنواع: جمع وجود ـ وهو جمع الزنادقة من أهل الاتّحاد ـ وجمع شهود، وجمع قصود. فإذا تحرّرت هذه الأقسام تحرّر الجمع الصحيح والفاسد.','терминологии этих людей это устремлённость духовной зоркости к Тому, от Кого исходят все разрозненные вещи. Он бывает трёх видов: собранность существования — собранность еретиков из сторонников единения; собранность созерцания и собранность стремления. Когда эти разновидности будут чётко разграничены, станут ясны правильная и порочная собранность.',False,True)
add(533,'وكذلك الفرق ينقسم إلى صحيح وفاسد، أعني إلى مطلوب في السلوك وإلى قاطع عن السلوك. فالفرق ثلاثة أنواع: فرق طبعيّ حيوانيّ، وفرق إسلاميّ، وفرق إيمانيّ، فهذه أقسام ستّة للجمع والفرق.','Так же и различение делится на правильное и порочное, то есть на требуемое в духовном пути и прерывающее его. Различение бывает трёх видов: естественное, животное различение; исламское различение и различение веры. Итак, у собранности и различения шесть разновидностей.')
add(533,'فنذكر أنواع الفرق أوّلًا، إذ بها تعرف أنواع الجمع.','Сначала рассмотрим виды различения, поскольку через них познаются виды собранности.')
add(533,'فأمّا الفرق الطبعيّ الحيوانيّ، فهو التفريق بمجرّد الطبع والميل، فيفرّق بين ما يفعله ولا يفعله بطبعه وهواه. وهذا فرق الحيوانات وأشباهها من بني آدم، فالمعيار: ميل طبعه، ونفرة طبعه. والمشركون والكفّار وأهل الظلم والعدوان واقفون مع هذا الفرق.','Что касается естественного, животного различения, то это разграничение лишь по природной склонности и влечению: человек различает, что ему делать, а чего не делать, по своему естеству и страсти. Таково различение животных и подобных им сынов Адама. Мерило здесь — влечение его природы и её отвращение. На этом различении останавливаются многобожники, неверующие, несправедливые и враждебные.')
add(533,'وأمّا الفرق الإسلاميّ، فهو الفرق بين ما شرعه الله وأمر به وأحبّه ورضيه، وبين ما نهى عنه وكرهه ومقت فاعله. وهذا الفرق من لم يكن من أهله لم يشمّ رائحة الإسلام البتّة. وقد حكى الله سبحانه عن أهل الفرق الطبعيّ أنّهم أنكروا هذا الفرق، فشهدوا الجمع بين المأمور والمحظور، فقالوا: {إِنَّمَا الْبَيْعُ مِثْلُ الرِّبَا} [البقرة: 275] لا فرق بينهما، وقالوا: الميتة','Исламское же различение — различение между тем, что Аллах узаконил, велел, полюбил и одобрил, и тем, что Он запретил, возненавидел и за что возненавидел совершающего это. Не обладающий таким различением вовсе не ощутил запаха ислама. Аллах, пречистый, рассказал о приверженцах естественного различения, что они отвергли это различение и усмотрели объединение веленного и запретного. Они сказали: {إِنَّمَا الْبَيْعُ مِثْلُ الرِّبَا} — «Торговля подобна ростовщичеству» [«Аль-Бакара», 2:275], — между ними нет различия. И сказали: «Мертвечина',False)
add(534,'مثل المذكّاة، لا فرق بينهما، وقالوا: الحلال والحرام شيء واحد. فهذا جمعهم وذاك فرقهم.','подобна заколотому по правилам животному: между ними нет различия». Они сказали: «Дозволенное и запретное — одно». Такова их собранность, а выше было их различение.',False,True)
add(534,'فصل','Раздел')
add(534,'فهذا فرق يتعلّق بالأعمال.','Это различение относится к деяниям.')
add(534,'وأمّا الفرق الإيمانيّ الذي يتعلّق بمسائل القضاء والقدر، فهو التمييز الإيمانيّ بين فعل الحقّ سبحانه وأفعال العباد. فيؤمن بأنّ الله وحده خالق كلّ شيء، وليس في الكون إلّا ما هو واقع بمشيئته وقدرته وخلقه؛ ومع ذلك يؤمن بأنّ العبد فاعل لأفعاله حقيقة، وهي صادرة عن قدرته ومشيئته قائمة به، وهو فاعل لها على الحقيقة. فيشهد تفرّد الربّ بالخلق والتقدير، ووقوع أفعال العباد منهم بقدرهم ومشيئتهم، والله خالق ذلك كلّه.','Различение веры, относящееся к вопросам решения и предопределения, — это различение посредством веры между действием Истинного, пречистого, и действиями рабов. Человек верит, что один Аллах — Творец всякой вещи и что всё в мироздании происходит по Его воле, могуществу и творению. Вместе с тем он верит, что раб действительно совершает свои действия: они исходят из его способности и воли, осуществляются в нём и он совершает их в действительности. Он созерцает единоличность Господа в творении и предопределении, а также то, что действия рабов совершаются ими посредством их способностей и воли; всё это создал Аллах.')
add(534,'وهنا انقسم أصحاب هذا الفرق ثلاثة أقسام: قسم غابوا بأفعالهم وحركاتهم عن فعل الربّ تعالى وقضائه، مع إيمانهم به؛ وقسم غابوا بفعل الربّ وتفرّده بالحكم والمشيئة عن أفعالهم وحركاتهم؛ وقسم أعطوا المراتب حقّها، فآمنوا بفعل الربّ وقدره ومشيئته، وتفرّده بالحكم والقضاء، وشهدوا وقوع الأفعال من فاعليها، واستحقاقهم عليها المدح والذمّ والثواب والعقاب.','Здесь обладатели этого различения разделились на три группы. Одни, будучи поглощены своими действиями и движениями, перестали замечать действие Господа Всевышнего и Его решение, хотя верят в него. Другие, будучи поглощены действием Господа и Его единоличностью в решении и воле, перестали замечать свои действия и движения. Третьи отдали каждому уровню должное: уверовали в действие Господа, Его предопределение и волю, Его единоличность в решении и суде и созерцали совершение действий теми, кто их совершает, и то, что за них они заслуживают похвалы, порицания, награды и наказания.')
add(534,'فالفريق الأوّل: يغلب عليهم الفرق الطبعيّ، إذ لم يصعدوا إلى مشاهدة الحكم.','В первой группе преобладает естественное различение, поскольку они не поднялись до созерцания решения.')
add(534,'والفريق الثاني: يغلب عليهم حال الجمع، وهو شهود قدر الربّ تعالى ومشيئته وتدبيره لخلقه، فتجتمع قلوبهم على شهود أفعاله بعد أن كانت','Во второй группе преобладает состояние собранности — созерцание предопределения Господа Всевышнего, Его воли и управления творением. Их сердца сосредоточиваются на созерцании Его действий после того, как были',False)
open(p,'w').write(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
add(535,'متفرّقة في رؤية أفعال الخلق، وتغيب بفعله عن أفعالهم. وربّما غلب عليهم شهود ذلك حتّى أسقط عنهم المدح والذمّ بالكلّيّة.','рассеяны в наблюдении действий творения; Его действие отвлекает их от действий людей. Иногда такое созерцание настолько овладевает ими, что совершенно устраняет для них похвалу и порицание.',False,True)
add(535,'وكلاهما منحرف في شهوده.','Обе группы уклоняются в своём созерцании.')
add(535,'والفريق الثالث: يشهد الحكم والتدبير العامّ لكلّ موجود، ويشهد أفعال العباد ووقوعها بإرادتهم ودواعيهم. فيكون صاحب جمع وفرق؛ فيجمع الأشياء في الحكم الكونيّ القدريّ، ويفرق بينها بالحكم الكونيّ أيضًا كما فرّق الله بينها، وبالدينيّ الشرعيّ؛ فإنّ الله سبحانه فرّق منها خلقًا وأمرًا قدرًا وشرعًا، كونًا ودينًا.','Третья группа созерцает решение и общее управление всяким существующим, созерцает действия рабов и их совершение по их воле и побуждениям. Такой человек обладает собранностью и различением: объединяет вещи в бытийном решении предопределения и различает их также бытийным решением, как их различил Аллах, и религиозным решением Закона. Ведь Аллах, пречистый, различил их в творении и повелении, в предопределении и Законе, в бытии и религии.')
add(535,'فالشهود الصحيح المطابق: أن يشهدها كذلك، فيكون صاحب جمع في فرق، وفرق في جمع: جمع بينها في الخلق والتكوين وشمول المشيئة لها، وفرق بينها بالأمر والنهي والحبّ والبغض، فشهدها وهي منقسمة إلى مأمور ومحظور، ومحبوب ومكروه، كما فرّق خالقها بينها. ويشهد الفرق بينها أيضًا قدرًا، فإنّه كما فرّق بينها أمره، فرّق بينها قدره، فقدّر المحبوب محبوبًا، والمسخوط مسخوطًا، والخير على ما هو عليه، والشرّ على ما هو عليه. فافترقت في قدره، كما افترقت في شرعه. فجمعها مشيئته وقدره، وفرّقت بينها مشيئته وقدره. فشاء سبحانه كلًّا منها أن يكون على ما هو عليه ذاتًا وقدرًا وصفة وأن يكون محبوبًا أو مسخوطًا، وأشهدها أهل البصائر من خلقه كما هي عليه.','Правильное созерцание, соответствующее действительности, — созерцать их именно так, сочетая собранность с различением и различение с собранностью. Он объединяет их в творении, приведении к бытию и охвате их волей, а различает повелением и запретом, любовью и ненавистью. Он созерцает их разделёнными на веленное и запретное, любимое и ненавистное, как их различил их Творец. Он созерцает различие между ними и в предопределении: как различило их Его повеление, так различило их и Его предопределение. Он предопределил любимое любимым, ненавистное ненавистным, добро таким, каково оно есть, а зло таким, каково оно есть. Они различаются в Его предопределении, как различаются в Его Законе. Его воля и предопределение объединили их, и Его воля и предопределение провели между ними различие. Он, пречистый, пожелал, чтобы каждая вещь была такой, какова она есть по своей сущности, мере и качеству, и чтобы была любимой или ненавистной; и Он дал духовно зорким из Своего творения созерцать их такими, каковы они есть.')
add(535,'فهؤلاء أصحّ الناس شهودًا، بخلاف من شهد المخلوق قديمًا، والوجود','У этих людей самое правильное созерцание — в отличие от того, кто созерцает сотворённое безначальным, существование',False)
add(536,'المخلوق هو عين الوجود الخالق، والمأمور والمحظور سواء، والمقدّر كلّه محبوب مرضيّ له، أو أنّ بعض الحادثات خارج عن مشيئته وخلقه وتكوينه، أو أنّ أفعال عباده خارجة عن إرادتهم ومشيئتهم وقدرتهم، وليسوا هم الفاعلين لها= فإنّ هذا الشهود كلّه عمى، وأصحابه قد جمعوا بين ما فرّق الله بينه، وفرّقوا بين ما جمع الله بينه، ولم يهتدوا إلى الشهود الصحيح الذي يميّز به صاحبه بين وجود الخالق ووجود المخلوق، وبين المأمور والمحظور، وبين فعل الربّ وفعل العبد، وبين ما يحبّه ويبغضه.','сотворённого — самим существованием Творца, веленное и запретное — одинаковыми, всё предопределённое — любимым и одобряемым Им; или считает, что некоторые возникающие вещи выходят за пределы Его воли, творения и приведения к бытию; или что действия Его рабов выходят за пределы их воли, желания и способности и совершаются не ими. Всё это созерцание — слепота. Его обладатели объединили то, что Аллах различил, и различили то, что Он объединил. Они не нашли правильного созерцания, посредством которого различают существование Творца и существование творения, веленное и запретное, действие Господа и действие раба, то, что Он любит, и то, что ненавидит.',False,True)
add(536,'وصاحب هذا الشهود لا يغيب بأفعال العباد عن فعل الربّ وقضائه وقدره، ولا يغيب بقضائه وقدره عن أمره ونهيه ومحبّته لبعضها وكراهته لبعضها، ولا يغيب بوجود الخالق عن وجود المخلوق، ولا برؤية الخلق عن ملاحظة الخالق؛ بل يضع الأمور مواضعها، فيشهد القدر العامّ السابق الذي لا خروج للمخلوق عنه، كما لا خروج له عن أن يكون مربوبًا فقيرًا بذاته، ويذمّ العباد ويمدحهم بما حرّكهم به القدر من المعاصي والطاعات؛ بخلاف صاحب الجمع بلا فرق، فإنّه ربّما عذر أرباب الشرك والمعاصي لاستيلاء شهود الجمع على قلبه، ويقول: العارف لا ينكر منكرًا لاستبصاره بسرّ الله في القدر، ولشهوده موافقتهم لما شاءه الله منهم.','Обладатель такого созерцания не перестаёт замечать действие Господа, Его решение и предопределение, поглощаясь действиями рабов; не перестаёт замечать Его повеление и запрет, любовь к одним действиям и неприязнь к другим, поглощаясь Его решением и предопределением; не перестаёт замечать существование творения, поглощаясь существованием Творца, и не упускает Творца, наблюдая творение. Он отводит вещам их места: созерцает всеобщее предшествующее предопределение, за пределы которого творению не выйти, как ему не выйти за пределы своей подвластности Господу и нужды по самой своей сути; и порицает или хвалит рабов за ослушание и послушание, к которым их привело предопределение. Иначе поступает обладатель собранности без различения: из-за овладевшего его сердцем созерцания собранности он порой оправдывает многобожников и грешников и говорит: «Познающий не порицает порицаемого, поскольку прозрел тайну Аллаха в предопределении и созерцает, что они соответствуют тому, чего Аллах пожелал от них».')
add(536,'فالشاهد المبصر المتمكّن يشهد القيّوميّة والقدر السابق الشامل','Поэтому зрячий и утвердившийся созерцающий созерцает поддержание всего сущего Господом и предшествующее всеобъемлющее предопределение,',False)
add(537,'المحيط، ويشهد اكتساب العباد وما جرى به عليهم القدر من الطاعات والمعاصي، ويشهد حكمة الربّ تعالى وأمره ونهيه وحبّه وكراهته.','объемлющее всё; созерцает приобретение рабами своих деяний и то послушание и ослушание, которое осуществляется в них по предопределению; созерцает мудрость Господа Всевышнего, Его повеление и запрет, любовь и неприязнь.',False,True)
add(537,'فصل','Раздел')
add(537,'إذا عرفت هذه المقدّمات فالجمع الصحيح الذي عليه أهل الاستقامة هو: جمع توحيد الربوبيّة وجمع توحيد الإلهيّة.','Когда ты усвоил эти предварительные положения, правильная собранность, которой придерживаются стойкие на прямом пути, — это собранность единобожия господства и собранность единобожия божественности.')
add(537,'فيشهد صاحبه قيّوميّة الربّ تعالى فوق عرشه يدبّر أمر عباده وحده. فلا خالق ولا رازق، ولا معطي ولا مانع، ولا مميت ولا محيي، ولا مدبّر لأمر المملكة ـ ظاهرًا وباطنًا ـ غيره. فما شاء كان، وما لم يشأ لم يكن. لا تتحرّك ذرّة إلّا بإذنه، ولا يجري حادث إلّا بمشيئته، ولا تسقط ورقة إلّا بعلمه، ولا يعزب عنه مثقال ذرّة في السماوات ولا في الأرض، ولا أصغر من ذلك ولا أكبر إلّا وقد أحصاها علمه، وأحاطت بها قدرته، ونفذت بها مشيئته، واقتضتها حكمته. فهذا جمع توحيد الربوبيّة.','Обладатель её созерцает, как Господь Всевышний, поддерживающий всё сущее, над Своим Престолом единолично управляет делами Своих рабов. Нет иного творца, подателя удела, дарующего и удерживающего, умерщвляющего и оживляющего, управляющего делами царства — явными и скрытыми, — кроме Него. Что Он пожелал, то произошло, а чего не пожелал, того не произошло. Ни пылинка не движется без Его дозволения, ни событие не происходит без Его воли, ни лист не падает без Его знания. От Него не ускользает вес пылинки ни на небесах, ни на земле, ни что-либо меньше или больше: всё исчислено Его знанием, охвачено Его могуществом, осуществляется по Его воле и требуется Его мудростью. Это собранность единобожия господства.')
add(537,'وأمّا جمع توحيد الإلهيّة، فهو: أن يجمع قلبه وهمّه وعزمه وإرادته وحركاته على أداء حقّه والقيام بعبوديّته، فتجتمع شؤون إرادته على مراده الدينيّ الشرعيّ.','А собранность единобожия божественности — сосредоточить своё сердце, устремление, решимость, волю и движения на исполнении Его права и рабском служении Ему, так чтобы все направления воли сошлись на том, чего Он желает в религии и Законе.')
add(537,'وهذان الجمعان هما حقيقة {إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ}. فإنّ العبد يشهد من قوله {إِيَّاكَ} الذات الجامعة لجميع صفات الكمال التي لها كلّ الأسماء الحسنى، ثمّ يشهد من قوله: {نَعْبُدُ} جميع أنواع العبادة','Эти две собранности — действительность слов {إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ} — «Тебе одному мы поклоняемся и Тебя одного просим о помощи». Из слова {إِيَّاكَ} — «Тебе одному» — раб созерцает Сущность, соединяющую все качества совершенства, Которой принадлежат все прекрасные имена. Затем из слова {نَعْبُدُ} — «мы поклоняемся» — он созерцает все виды поклонения,',False)
open(p,'w').write(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
add(538,'ظاهرًا وباطنًا، قولًا وعملًا، حالًا واستقبالًا. ثمّ يشهد من قوله: {وَإِيَّاكَ نَسْتَعِينُ} جمع الاستعانة والتوكّل والتفويض، فيشهد منه جمع الربوبيّة. ويشهد من {إِيَّاكَ نَعْبُدُ} جمع الإلهيّة، ويشهد من {إِيَّاكَ} الذات الجامعة لكلّ الأسماء الحسنى والصفات العلا.','явные и скрытые, словесные и деятельные, в настоящем и будущем. Затем из слов {وَإِيَّاكَ نَسْتَعِينُ} — «и Тебя одного просим о помощи» — созерцает собранность испрашивания помощи, упования и вверения дел: в этом он созерцает собранность господства. Из слов {إِيَّاكَ نَعْبُدُ} — «Тебе одному мы поклоняемся» — он созерцает собранность божественности, а из слова {إِيَّاكَ} — «Тебе одному» — Сущность, соединяющую все прекрасные имена и высочайшие качества.',False,True)
add(538,'ثمّ يشهد من {اهْدِنَا} عشر مراتب، إذا اجتمعت حصلت الهداية:','Затем из слова {اهْدِنَا} — «Веди нас» — он созерцает десять степеней, при соединении которых обретается руководство:')
add(538,'المرتبة الأولى: هداية العلم والبيان، فيجعله عالمًا بالحقّ مدركًا له.','Первая степень — руководство знанием и разъяснением: Он делает его знающим истину и постигающим её.')
add(538,'الثانية: أن يقدره عليه، وإلّا فهو غير قادر بنفسه.','Вторая — наделить его способностью к этому, иначе сам по себе он на это не способен.')
add(538,'الثالثة: أن يجعله مريدًا له.','Третья — сделать его желающим этого.')
add(538,'الرابعة: أن يجعله فاعلًا له.','Четвёртая — сделать его осуществляющим это.')
add(538,'الخامسة: أن يثبّته على ذلك، ويستمرّ به عليه.','Пятая — утвердить его в этом и обеспечить его постоянство в нём.')
add(538,'السادسة: أن يصرف عنه الموانع والعوارض المضادّة له.','Шестая — отвратить от него препятствия и противодействующие этому помехи.')
add(538,'السابعة: أن يهديه في الطريق نفسها هداية خاصّة أخصّ من الأولى، فإنّ الأولى هداية إلى الطريق إجمالًا، وهذه هداية فيها وفي منازلها تفصيلًا.','Седьмая — вести его на самом пути особым руководством, более частным, чем первое: первое — руководство к пути в общем, а это — подробное руководство на нём и в его обителях.')
add(538,'الثامنة: أن يشهده المقصود في طريقه وينبّهه عليه، فيكون مطالعًا له في سيره، ملتفتًا إليه، غير محتجب بالوسيلة عنه.','Восьмая — дать ему созерцать цель на его пути и обратить на неё его внимание, чтобы в своём движении он обозревал её и обращался к ней, чтобы средство не заслоняло её от него.')
